/* Cuddle: the badge and quest-reward icons, by id. Generated by
 * scripts/build-badge-icons.js -- edit that, not this.
 *
 * CuddleBadgeArt.img(id) is the icon every page shows for a badge (the
 * badge page, packs, the shop, help, reward cards), so a badge looks the
 * same everywhere.
 */
(function () {
  "use strict";
  if (window.CuddleBadgeArt) return;
  var IDS = new Set(["allThemesBoss","alphabet-compass","ascetic","bigOpener","biggerMulligans","blackMarket","boldOpener","bonusSquares","categorySense","cleanSlate","coachMeterReward","coachMeterThreshold","coachPossibleAnswers","colourTrade","combine","consonantSweep","cullOne","cullRare","cullTwo","doubleDown","doubleMulligans","earlySolveBoost","echoFinder","encore","extraLetters","extraMulligans","fastLane","fishHook","freeVowelSweep","fullCircle","goldenLedger","goldenOpener","gracePeriod","greenCount","greyscale","haggler","handSizeBoost","hardMode","highRoller","ideaTiles","insertCoin","jokerCache","jokerCacheLarge","jokerTiles","jokerToken","lastLight","lastStand","leanBuild","luckyClover","mistakeShield","momentum","monksVow","mulliganSize","mulliganTiles","mulliganValueBoost","oracleTiles","overtime","patternLens","pickpocket","questCadence","questChain","questClue","questDoublePick","questMastery","questPersistReward","questPoints","questRefreshes","questReroll","questScout","rainyDay","revealCategory","revealGreen","rewardEcho","secondCup","sillyWord","stealthGuess","storybookStart","strikeThrough","surprise-assignment","treasureChest","treasureHunter","treasureMap","umtClue","umtFishingLine","umtPocketMoney","umtQuickPoints","umtRuleOut","umtSpotlight","umtVowelCheck","vowelBounty","vowelLamp","waveTiles","wideChoice","yellowHint"]);
  function slug(id) {
    return String(id).replace(/([a-z0-9])([A-Z])/g, "$1-$2").replace(/[^a-zA-Z0-9]+/g, "-").replace(/^-+|-+$/g, "").toLowerCase();
  }
  // Some layers name a badge with a "umt" prefix (umtCullOne for cullOne).
  function key(id) {
    var text = String(id || "");
    if (IDS.has(text)) return text;
    var bare = /^umt[A-Z]/.test(text) ? text.charAt(3).toLowerCase() + text.slice(4) : "";
    return bare && IDS.has(bare) ? bare : "";
  }
  function has(id) { return Boolean(key(id)); }
  function url(id) { return "cuddle/icons/reward-" + slug(key(id) || id) + ".svg"; }
  function img(id, className) {
    return '<img class="umt-badge-art' + (className ? " " + className : "") + '" src="' + url(id) + '" alt="" aria-hidden="true" draggable="false">';
  }
  window.CuddleBadgeArt = Object.freeze({ has: has, key: key, url: url, img: img });
}());
